/**
 *
 * TreeNode renders a single row inside a flat-iterated `Tree.Nodes`.
 *
 * [Live Demo](https://www.primereact.org/tree/)
 *
 * @module TreeNode
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { TreeNodeData, UseTreeNodeContentElProps, UseTreeNodeDropPointElProps, UseTreeNodeProps as UseTreeNodeElProps, UseTreeNodeState } from '@primereact/types/headless/tree';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { TreeRootInstance } from './TreeRoot.types';
/**
 * Type definition for tree node data.
 */
export type { TreeNodeData } from '@primereact/types/headless/tree';
/**
 * Defines passthrough(pt) options type in TreeNode component.
 */
export type TreeNodePassThroughType<E> = PassThroughType<TreeNodeInstance, E>;
/**
 * Defines passthrough(pt) options of TreeNode component.
 */
export interface TreeNodePassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TreeNodePassThroughType<React.HTMLAttributes<HTMLLIElement>>;
}
/**
 * Defines valid properties in TreeNode component.
 */
export interface TreeNodeProps extends BaseComponentProps<TreeNodeInstance, unknown, TreeNodePassThrough> {
    /**
     * The key of the node to render. Looked up in the parent `Tree.Root`'s `nodeMap`.
     * If the key is unknown (or omitted) a placeholder with `aria-busy` is rendered
     * and a dev-mode warning is emitted.
     */
    uKey?: string;
}
/**
 * Defines valid state in TreeNode component.
 */
export interface TreeNodeState {
}
/**
 * Defines the methods and properties exposed by TreeNode component.
 */
export interface TreeNodeExposes {
    /**
     * The Tree component instance.
     */
    tree: TreeRootInstance | undefined | null;
    /**
     * The parent TreeNode component instance (in the React tree, not the data tree).
     */
    parentNode: TreeNodeInstance | undefined | null;
    /**
     * The underlying node data (looked up from `uKey`).
     */
    node: TreeNodeData | undefined;
    /**
     * The computed state from useTreeNode headless hook.
     */
    state: UseTreeNodeState;
    /**
     * Pre-built props for the node root element (li).
     */
    nodeProps: UseTreeNodeElProps | undefined;
    /**
     * Pre-built props for the content element (div).
     */
    contentProps: UseTreeNodeContentElProps;
    /**
     * Pre-built props for drop point indicators.
     */
    dropPointProps: UseTreeNodeDropPointElProps;
    /**
     * Whether the node is expanded.
     */
    expanded: boolean;
    /**
     * Whether the node is checked (for checkbox mode).
     */
    checked: boolean;
    /**
     * Whether the node is partially checked (for checkbox mode).
     */
    partialChecked: boolean;
    /**
     * Whether the node is selected (for single/multiple mode).
     */
    selected: boolean | undefined;
    /**
     * Whether the node is a leaf node (has no children).
     */
    leaf: boolean;
    /**
     * The total number of siblings at this level.
     */
    setSize: number;
    /**
     * The position of this node among its siblings (1-based).
     */
    posInSet: number;
    /**
     * The depth level of the node in the tree (1-based).
     */
    level: number;
    /**
     * Whether this node is currently being dragged over (center zone).
     */
    isNodeDropActive: boolean;
    /**
     * Whether the previous drop point is active.
     */
    isPrevDropPointActive: boolean;
    /**
     * Whether the next drop point is active.
     */
    isNextDropPointActive: boolean;
    /**
     * Whether this node is draggable.
     */
    isDraggable: boolean;
    /**
     * Whether the node was touched (for mobile interactions).
     */
    nodeTouched: boolean;
}
/**
 * Instance of TreeNode component.
 */
export type TreeNodeInstance = ComponentInstance<TreeNodeProps, TreeNodeState, TreeNodeExposes>;
